require '../../includes/header.php';require '../../includes/role_guard.php';requireRole(['admin','staff','tribe_leader','tribe_rep','assessor']);require '../../includes/db.php';require_once '../../includes/tax_access.php';$t=require_tax_access($conn,(int)($_GET['id']??0));
