<section class="card-box mb-3"><div class="section-title">Assessments</div><div class="table-responsive"><table class="table"><thead><tr><th>Classification</th><th>Area</th><th>Market Value</th><th>Actual Use</th><th>Level</th><th>Assessed Value</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=e($r['classification'])?></td><td><?=e($r['area_sqm'])?></td><td><?=e($r['market_value'])?></td><td><?=e($r['actual_use'])?></td><td><?=e($r['assessment_level_percent'])?>%</td><td><?=e($r['assessed_value'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card-box"><div class="section-title">Case, Parcel and Evidence Links</div><?php if($t['parcel_id']):?><p><strong>Mapped parcel:</strong> <?=e($t['parcel_name'])?> <a href="../admin/gis.php?parcel_id=<?=$t['parcel_id']?>">View map evidence</a></p><?php else:?><p class="text-muted">No mapped parcel. Textual boundaries remain preserved without generated geometry.</p><?php endif;?><?php foreach($cases as$c):?><span class="badge bg-secondary me-1"><?=e($c['case_title'])?></span><?php endforeach;?><?php foreach($files as$f):?><p class="mt-2"><a href="../../processes/tax_attachment.php?id=<?=$f['id']?>"><i class="bi bi-lock"></i> <?=e($f['file_name'])?></a></p><?php endforeach;?></section></main><?php require '../../includes/footer.php';?>
